{"content": "1|import { Injectable, HttpException, HttpStatus, Logger } from '@nestjs/common';
2|import { PrismaService } from '../prisma/prisma.service';
3|import { DeviceService } from '../device/device.service';
4|import { SupabaseService } from '../supabase/supabase.service';
5|import { TrackBatchDto } from './dto/track-batch.dto';
6|import { BUSINESS_RULES } from '../../common/constants/business-rules';
7|
8|@Injectable()
9|export class FleetService {
10|  constructor(
11|    private readonly prisma: PrismaService,
12|    private readonly deviceService: DeviceService,
13|    private readonly supabaseService: SupabaseService,
14|  ) {}
15|
16|  /**
17|   * Return all devices in the fleet, determining online/offline status logically.
18|   */
19|  async getFleetDevices() {
20|    const devices = await this.prisma.device.findMany({
21|      select: {
22|        id: true,
23|        deviceId: true,
24|        taxiNumber: true,
25|        lastSeen: true,
26|        batteryLevel: true,
27|        playerStatus: true,
28|        storageFree: true,
29|        storageUsed: true,
30|        storageTotal: true,
31|        appVersion: true,
32|        status: true,
33|        city: true,
34|        fleet: true,
35|        lastHeartbeat: true,
36|        lastPlayback: true,
37|        driver: {
38|          select: {
39|            fullName: true,
40|            id: true,
41|          }
42|        }
43|      },
44|      orderBy: {
45|        lastSeen: 'desc',
46|      }
47|    });
48|
49|    const now = new Date();
50|    // 30 min in ms
51|    const tenMinMs = 10 * 60 * 1000;
52|
53|    return devices.map((d) => {
54|      let isOnline = false;
55|      if (d.lastSeen && now.getTime() - d.lastSeen.getTime() <= tenMinMs) {
56|        isOnline = true;
57|      }
58|
59|      return {
60|        ...d,
61|        id: d.id,
62|        device_id: d.deviceId,
63|        status: isOnline ? 'online' : (d.status === BUSINESS_RULES.STATUS.DEVICE.SUSPENDED ? 'inactive' : 'offline'),
64|        last_seen: d.lastSeen,
65|        battery_level: d.batteryLevel,
66|        player_status: d.playerStatus,
67|        storage_free: d.storageFree,
68|        storage_used: d.storageUsed ? Number(d.storageUsed) : null,
69|        storage_total: d.storageTotal ? Number(d.storageTotal) : null,
70|        is_online: isOnline,
71|        driver_name: d.driver?.fullName || 'Sín Conductor',
72|        last_playback: d.lastPlayback,
73|      };
74|    });
75|  }
76|
77|  async getFleetStats() {
78|    const tenMinAgo = new Date(Date.now() - 10 * 60 * 1000);
79|
80|    // Executes parallel micro-queries in Supabase, leveraging indices
81|    const [total, online, withErrors] = await Promise.all([
82|      this.prisma.device.count(),
83|      this.prisma.device.count({
84|        where: { lastSeen: { gte: tenMinAgo } }
85|      }),
86|      this.prisma.device.count({
87|        // Devices with a playerStatus that is not null and not empty string
88|        where: {
89|          playerStatus: {
90|            not: null,
91|          },
92|          NOT: {
93|            playerStatus: {
94|              in: ['playing', '']
95|            }
96|          }
97|        }
98|      })
99|    ]);
100|
101|    return {
102|      total,
103|      online,
104|      offline: total - online,
105|      withErrors
106|    };
107|  }
108|
109|  async getFleetMap(advertiserId?: string) {
110|    try {
111|      const now = new Date();
112|      const onlineWindowMs = 90 * 1000;
113|
114|      // Build filter: if advertiserId is provided, only show devices assigned to their campaigns
115|      const where: Record<string, unknown> = {};
116|      if (advertiserId) {
117|        where.campaigns = {
118|          some: {
119|            campaign: {
120|              advertiserId: advertiserId,
121|              active: true,
122|              startDate: { lte: now },
123|              endDate: { gte: now },
124|            }
125|          }
126|        };
127|      }
128|
129|      const devices = await this.prisma.device.findMany({
130|        where,
131|        select: {
132|          id: true,
133|          deviceId: true,
134|          driverId: true,
135|          taxiNumber: true,
136|          city: true,
137|          lastSeen: true,
138|          lastLat: true,
139|          lastLng: true,
140|          status: true,
141|          driver: {
142|            select: {
143|              id: true,
144|              fullName: true,
145|              taxiPlate: true,
146|              licensePlate: true,
147|              status: true,
148|              subscriptionPaid: true,
149|              subscriptionEnd: true,
150|            }
151|          },
152|          locations: {
153|            orderBy: { timestamp: 'desc' },
154|            take: 1,
155|            select: {
156|              latitude: true,
157|              longitude: true,
158|              speed: true,
159|              timestamp: true,
160|            },
161|          }
162|        }
163|      });
164|
165|      return devices.map(d => {
166|        const lastLocation = d.locations[0] || null;
167|        const lastLat = d.lastLat ?? lastLocation?.latitude ?? null;
168|        const lastLng = d.lastLng ?? lastLocation?.longitude ?? null;
169|        const lastSeen = d.lastSeen ?? lastLocation?.timestamp ?? null;
170|        const isOnline = !!(lastSeen && (now.getTime() - new Date(lastSeen).getTime()) <= onlineWindowMs);
171|
172|        // Derive subscription status from the flag + expiry date (simpler, no nested query)
173|        let subscriptionStatus = 'PENDING';
174|        if (d.driver) {
175|          if (d.driver.subscriptionPaid) {
176|            const notExpired = !d.driver.subscriptionEnd || d.driver.subscriptionEnd > now;
177|            subscriptionStatus = notExpired ? 'ACTIVE' : 'EXPIRED';
178|          } else {
179|            subscriptionStatus = d.driver.status || 'PENDING';
180|          }
181|        }
182|
183|        return {
184|          driverId: d.driver?.id ?? d.driverId ?? null,
185|          deviceId: d.deviceId,
186|          taxiNumber: d.taxiNumber ?? null,
187|          city: d.city ?? null,
188|          lastSeen,
189|          lastLat,
190|          lastLng,
191|          status: d.status,
192|          isOnline,
193|          driverName: d.driver?.fullName ?? null,
194|          plate: d.driver?.taxiPlate ?? d.driver?.licensePlate ?? null,
195|          subscriptionStatus,
196|          speed: lastLocation?.speed ?? null,
197|        };
198|      });
199|    } catch (error: unknown) {
200|      const errorMessage = error instanceof Error ? error.message : String(error);
201|      // Never crash the map page — return empty array with a warning log
202|      const logger = new Logger('FleetService');
203|      logger.error(`[FleetService] getFleetMap() failed — returning empty array: ${errorMessage}`);
204|      return [];
205|    }
206|  }
207|
208|  async getOfflineDevices() {
209|    const tenMinAgo = new Date(Date.now() - 10 * 60 * 1000);
210|    return this.prisma.device.findMany({
211|      where: {
212|        OR: [
213|          { lastSeen: { lt: tenMinAgo } },
214|          { lastSeen: null }
215|        ]
216|      },
217|      select: {
218|        deviceId: true,
219|        taxiNumber: true,
220|        lastSeen: true,
221|      }
222|    });
223|  }
224|
225|  /**
226|   * Real financial data: playback counts per device + subscription status.
227|   * Replaces all simulated/hardcoded finance calculations.
228|   */
229|  async getFleetFinance() {
230|    const RATE_PER_AD = 1.25; // RD$ per 30s ad play
231|
232|    // Get current month boundaries
233|    const now = new Date();
234|    const startOfMonth = new Date(now.getFullYear(), now.getMonth(), 1);
235|    const endOfMonth = new Date(now.getFullYear(), now.getMonth() + 1, 0, 23, 59, 59);
236|
237|    // Count real playback events per device for this month
238|    const playbackCounts = await this.prisma.playbackEvent.groupBy({
239|      by: ['deviceId'],
240|      _count: { id: true },
241|      where: {
242|        timestamp: {
243|          gte: startOfMonth,
244|          lte: endOfMonth,
245|        },
246|      },
247|    });
248|
249|    // Build a map: deviceId -> playCount
250|    const playsMap = new Map<string, number>();
251|    for (const row of playbackCounts) {
252|      playsMap.set(row.deviceId, row._count.id);
253|    }
254|
255|    // Get all devices with driver + subscription info
256|    const devices = await this.prisma.device.findMany({
257|      include: {
258|        driver: {
259|          include: {
260|            subscriptions: {
261|              where: { status: 'ACTIVE' },
262|              orderBy: { dueDate: 'desc' },
263|              take: 1,
264|            },
265|          },
266|        },
267|      },
268|    });
269|
270|    const tenMinMs = 10 * 60 * 1000;
271|
272|    const fleetFinance = devices.map((d) => {
273|      const isOnline = d.lastSeen && now.getTime() - d.lastSeen.getTime() <= tenMinMs;
274|      const adsPlayed = playsMap.get(d.deviceId) || 0;
275|      const revenue = parseFloat((adsPlayed * RATE_PER_AD).toFixed(2));
276|      const subscription = d.driver?.subscriptions?.[0] || null;
277|
278|      return {
279|        device_id: d.deviceId,
280|        display_name: d.taxiNumber || d.name || `TAXI-${d.deviceId.slice(0, 8).toUpperCase()}`,
281|        city: d.city || 'Santo Domingo',
282|        status: isOnline ? 'online' : 'offline',
283|        ads_played: adsPlayed,
284|        revenue,
285|        driver: d.driver ? {
286|          name: d.driver.fullName,
287|          phone: d.driver.phone,
288|          status: d.driver.status,
289|        } : null,
290|        subscription: subscription ? {
291|          plan: subscription.plan,
292|          amount: subscription.amount,
293|          status: subscription.status,
294|          paid: !!subscription.paidAt,
295|          expiresAt: subscription.validUntil,
296|        } : null,
297|      };
298|    });
299|
300|    const totalRevenue = fleetFinance.reduce((sum, d) => sum + d.revenue, 0);
301|    const totalAds = fleetFinance.reduce((sum, d) => sum + d.ads_played, 0);
302|
303|    return {
304|      period: `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, '0')}`,
305|      rate_per_ad: RATE_PER_AD,
306|      total_revenue: parseFloat(totalRevenue.toFixed(2)),
307|      total_ads_played: totalAds,
308|      devices: fleetFinance.sort((a, b) => b.revenue - a.revenue),
309|    };
310|  }
