312|  async sendCommand(deviceId: string, type: string, params: Record<string, unknown> = {}) {
313|    return this.prisma.deviceCommand.create({
314|      data: {
315|        deviceId: (await this.prisma.device.findUnique({ where: { deviceId } }))?.id || deviceId,
316|        commandType: type,
317|        commandParams: JSON.stringify(params || {}),
318|        status: 'PENDING',
319|        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000), // 7 days
320|      }
321|    });
322|  }
