4|import { NotificationsService } from '../notifications/notifications.service';
5|import { BUSINESS_RULES } from '../../common/constants/business-rules';
6|
7|@Injectable()
8|export class FleetMonitorService {
9|  private readonly logger = new Logger(FleetMonitorService.name);
10|
11|  constructor(
12|    private readonly prisma: PrismaService,
13|    private readonly notifications: NotificationsService
14|  ) {}
15|
16|  @Cron(CronExpression.EVERY_12_HOURS)
17|  async checkFleetConnectivity() {
18|    this.logger.log('Iniciando auditoría de conectividad de flota...');
19|    const now = new Date();
20|    const threshold48h = new Date(now.getTime() - 48 * 60 * 60 * 1000);
21|    const threshold12h = new Date(now.getTime() - 12 * 60 * 60 * 1000);
22|
23|    // 1. Marcar connectivity_issue para > 48h
24|    const devicesToUpdate = await this.prisma.device.updateMany({
25|      where: {
26|        lastHeartbeat: { lt: threshold48h },
27|        connectivityStatus: 'ONLINE'
28|      },
29|      data: { connectivityStatus: 'CONNECTIVITY_ISSUE' }
30|    });
31|
32|    if (devicesToUpdate.count > 0) {
33|      this.logger.warn(`🛑 ${devicesToUpdate.count} dispositivos marcados con 'connectivity_issue' (offline > 48h).`);
34|    }
35|
36|    // 2. Notificaciones push cada 12h sin conexión
37|    const offlineDevices = await this.prisma.device.findMany({
38|      where: { 
39|        lastHeartbeat: { lt: threshold12h },
40|        status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE
41|      },
42|      include: { driver: true }
43|    });
44|
45|    for (const device of offlineDevices) {
46|      if (device.driverId) {
47|        await this.notifications.sendPush(
48|          device.driverId,
49|          `⚠️ Alerta de Conexión: Su pantalla no ha reportado actividad en más de 12 horas. Asegúrese de que el GPS y el Internet estén activos.`
50|        ).catch(err => this.logger.error(`Error enviando push a ${device.driverId}: ${err.message}`));
51|      }
52|    }
53|    
54|    this.logger.log(`Auditoría de conectividad completada. Dispositivos offline > 12h: ${offlineDevices.length}`);
55|  }
