103|    : '&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a> contributors';
104|
105|  // Support both old (taxis) and new (locations) data format
106|  const dataToRender = locations || taxis || [];
107|  const currentMode = mode === 'heatmap' || heatmapMode ? true : false;
108|
109|  return (
