165|                      isOnline ? 'bg-green-100 text-green-800' : 'bg-red-100 text-red-800'
166|                    }`}>
167|                      {isOnline ? 'Online' : 'Offline'}
168|                    </span>
169|                  </p>
170|                  {(item.speed !== undefined || item.velocity !== undefined) && (
171|                    <p><strong>Speed:</strong> {item.speed || item.velocity || 0} km/h</p>
172|                  )}
173|                  {(item.last_update || item.updated_at) && (
174|                    <p className="text-xs text-gray-500 mt-2">
175|                      Updated: {new Date(item.last_update || item.updated_at).toLocaleTimeString()}
176|                    </p>
177|                  )}
178|                </div>
179|              </div>
180|            </Popup>
181|          </Marker>
182|        );
183|      })}
184|    </MapContainer>
185|  );
186|}
