648|    }).catch(e => Logger.error(`[FLEET_C2] Realtime broadcast failed: ${e.message}`));
649|
650|    // 2. Registrar en DeviceCommand para dispositivos offline/desconectados
651|    const activeDevices = await this.prisma.device.findMany({
652|        where: { status: BUSINESS_RULES.STATUS.DEVICE.ACTIVE },
