702|  /**
703|   * Procesa un lote de puntos GPS con validación de reglas de negocio críticas.
704|   * R3: Kill-Switch si la suscripción no está al día.
705|   * R2: Inserción masiva para optimizar latencia en producción.
706|   *
707|   * V12.1.3 (B3 PATCH): Ahora `skipDuplicates: true` es funcional porque
708|   * `DriverLocation.@@unique([deviceId, timestamp])` existe (migración
709|   * `20260110_driver_location_unique`). Sin UNIQUE el flag era NO-OP.
710|   *
711|   * Adicional: luego del createMany se hace un UPSERT del "last location" del
712|   * dispositivo (lastSeen/lastLat/lastLng) idempotente.
713|   */
714|  async ingestTelemetryBatch(data: TrackBatchDto) {
715|    const logger = new Logger('FleetService');
716|
717|    // Defensa: payload vacío no debería llegar aquí (DTO valida IsArray),
718|    // pero protegemos contra puntos vacíos para no desperdiciar round-trip.
719|    if (!data?.points || data.points.length === 0) {
720|      logger.warn(`⚠️ Telemetry batch with 0 points from driver [${data?.driverId ?? 'unknown'}]`);
721|      return { count: 0 };
722|    }
723|
724|    // 1. Validar existencia del conductor
725|    const driver = await this.prisma.driver.findUnique({
726|      where: { id: data.driverId },
727|      select: { id: true, subscriptionPaid: true, status: true, fullName: true }
728|    });
729|
730|    if (!driver) {
731|      logger.warn(`⚠️ Telemetry Rejected: Driver [${data.driverId}] not found.`);
732|      throw new HttpException('Driver Not Found', HttpStatus.NOT_FOUND);
733|    }
734|
735|    // 2. Regla de Negocio #3: Kill-Switch si la suscripción no está al día
736|    if (driver.status !== BUSINESS_RULES.STATUS.DRIVER.ACTIVE || !driver.subscriptionPaid) {
737|      logger.warn(`🚫 Telemetry Rejected (402): Driver [${driver.fullName}] is delinquent or inactive.`);
738|      throw new HttpException('Payment Required - Subscription Inactive', HttpStatus.PAYMENT_REQUIRED);
739|    }
740|
741|    // 3. Inserción Masiva (Batching) para optimizar I/O (Regla de Negocio #2).
742|    //    `skipDuplicates: true` ahora es funcional gracias al UNIQUE constraint
743|    //    y previene que el mismo (deviceId, timestamp) duplique filas.
744|    const telemetryData = data.points.map(p => ({
745|      driverId: data.driverId,
746|      deviceId: data.deviceId,
747|      latitude: p.lat,
748|      longitude: p.lng,
749|      speed: p.speed,
750|      timestamp: new Date(p.timestamp),
751|    }));
752|
753|    const result = await this.prisma.driverLocation.createMany({
754|      data: telemetryData,
755|      skipDuplicates: true, // B3 PATCH: ahora SÍ funciona (UNIQUE existe)
756|    });
757|
758|    logger.log(`✅ Telemetry Batch Processed: ${result.count} points from [${driver.fullName}] (input=${telemetryData.length})`);
759|
760|    // 4. Update Device 'lastSeen' and current position (idempotente)
761|    if (data.points.length > 0) {
762|      const lastPoint = data.points[data.points.length - 1];
763|      await this.prisma.device.update({
764|        where: { deviceId: data.deviceId },
765|        data: {
766|          lastSeen: new Date(),
767|          lastLat: lastPoint.lat,
768|          lastLng: lastPoint.lng,
769|        }
770|      }).catch(e => logger.error(`Failed to update device status: ${e.message}`));
771|    }
772|
773|    return { count: result.count, input: telemetryData.length };
774|  }
