83|const isFreshTelemetry = (timestamp?: string | null) => {
84|  if (!timestamp) return false;
85|  const ts = new Date(timestamp).getTime();
86|  return Number.isFinite(ts) && Date.now() - ts <= OFFLINE_THRESHOLD_MS;
87|};
