105|const normalizeTelemetryPing = (payload: any): TelemetryPing | null => {
106|  if (!payload) return null;
107|  const driverId = typeof payload.driverId === 'string' ? payload.driverId : '';
108|  const deviceId = typeof payload.deviceId === 'string' ? payload.deviceId : '';
109|  const lat = Number(payload.lat);
110|  const lng = Number(payload.lng);
111|  const speed = Number(payload.speed ?? 0);
112|  const bearing = Number(payload.bearing ?? 0);
113|  const timestamp = typeof payload.timestamp === 'string' ? payload.timestamp : '';
114|
115|  if (!driverId || !deviceId || !Number.isFinite(lat) || !Number.isFinite(lng) || !timestamp) {
116|    return null;
117|  }
118|
119|  return { driverId, deviceId, lat, lng, speed, bearing, timestamp };
120|};
121|
122|const upsertTelemetryPing = (vehicles: Device[], ping: TelemetryPing) => {
123|  const idx = vehicles.findIndex((vehicle) =>
124|    String(vehicle.deviceId || '') === ping.deviceId
125|  );
126|
127|  const patch = {
128|    ...ping,
129|    lastLat: ping.lat,
130|    lastLng: ping.lng,
131|    lastSeen: ping.timestamp,
132|    isOnline: true,
133|  };
134|
135|  if (idx === -1) {
136|    return [
137|      ...vehicles,
138|      {
139|        deviceId: ping.deviceId,
140|        taxiNumber: ping.deviceId,
141|        isOnline: true,
142|        lastSeen: ping.timestamp,
143|        lastLat: ping.lat,
144|        lastLng: ping.lng,
145|        driverName: 'Unidad nueva',
146|        plate: undefined,
147|        city: undefined,
148|        batteryLevel: undefined,
149|        subscriptionStatus: 'ACTIVE',
150|        speed: ping.speed,
151|      } as Device,
152|    ];
153|  }
154|
155|  const next = vehicles.slice();
156|  next[idx] = { ...next[idx], ...patch } as Device;
157|  return next;
158|};
