7|// Safe BigInt serialization for Prisma
8|declare global {
9|  interface BigInt {
10|    toJSON(): string;
11|  }
12|}
13|
14|// Only override toJSON if not already defined (prevents duplicate definitions)
15|if (!BigInt.prototype.toJSON) {
16|  (BigInt.prototype as any).toJSON = function () {
17|    return this.toString();
18|  };
19|}
