21|async function bootstrap() {
22|  const logger = new Logger('Bootstrap');
23|  try {
24|    // B16 PATCH (v12.1.3): fail-fast en producción si JWT_SECRET no está
25|    // configurado. Sin esto, la app arranca y firma JWTs con `undefined`,
26|    // permitiendo a cualquier cliente forjar tokens válidos.
27|    if (process.env.NODE_ENV === 'production' && !process.env.JWT_SECRET) {
28|      logger.error('❌ FATAL: JWT_SECRET no configurado en producción. Abortando arranque.');
29|      process.exit(1);
30|    }
31|
32|    // Forzamos el buffer de logs para capturar errores prematuros de inyección
33|    const app = await NestFactory.create(AppModule, {
34|      bufferLogs: true,
35|      logger: ['error', 'warn', 'log', 'debug'], 
36|    });
37|
38|    // Prevención de fugas de conexiones (Auditoría 07)
39|    const prismaService = app.get(PrismaService);
40|    app.enableShutdownHooks();
41|
42|    app.setGlobalPrefix('api/v1', {
43|      exclude: [
44|        { path: '/', method: RequestMethod.GET },
45|        { path: 'api', method: RequestMethod.GET },
46|        { path: 'api/health', method: RequestMethod.GET },
47|        { path: 'api/v1', method: RequestMethod.GET },
48|        { path: 'health', method: RequestMethod.GET },
49|      ],
50|    });
