157|        // 1. Acumular punto en el Buffer Local (IndexedDB)
158|        const addPoint = async () => {
159|          const db = await dbPromise;
160|          await db.add(STORE_NAME, {
161|            device_id: localStorage.getItem('TAD_DEVICE_ID') || 'unknown',
162|            driver_id: driverId,
163|            latitude: position.coords.latitude,
164|            longitude: position.coords.longitude,
165|            speed: position.coords.speed || 0,
166|            captured_at: new Date(position.timestamp).toISOString(),
167|          });
168|        };
169|        addPoint().catch(console.error);
170|
171|        // 5-minute debounce for bulk flush (300,000 ms)
172|        if (now - lastSyncTime.current < 300000) return;
173|        
174|        // No sincronizar si no hay red
