{"content": "1|// apps/driver/hooks/useTelemetry.ts
2|/**
3| * useTelemetry — Hook de Telemetría Offline-First con soporte para IndexedDB
4| *
5| * Reglas de negocio:
6| *  - Agrupa coordenadas en lotes de BATCH_SIZE (10) o flushea cada FLUSH_INTERVAL_MS (300s)
7| *  - Almacena el buffer en IndexedDB para mayor resiliencia
8| *  - Al recibir HTTP 402 del backend → destruye el worker GPS y activa el kill-switch
9| *  - Sin dependencias de librerías de UI externas
10| */
11|
12|import { useEffect, useRef, useCallback, useState } from 'react';
13|import { usePaymentStore } from '../store/usePaymentStore';
14|import { openDB } from '../utils/indexedDb';
15|
16|// ─── Constantes ──────────────────────────────────────────────────────────────
17|const BATCH_SIZE = 10;
18|const FLUSH_INTERVAL_MS = 300_000; // 5 minutos (debounce estricto V12)
19|const MAX_OFFLINE_RECORDS = 500;
20|
21|export type ConnectionStatus = 'online' | 'offline' | 'syncing';
22|
23|export interface TelemetryCoord {
24|  lat: number;
25|  lng: number;
26|  ts: number;
27|  accuracy?: number;
28|}
29|
30|export interface UseTelemetryReturn {
31|  connectionStatus: ConnectionStatus;
32|  batchCount: number;     // coordenadas actuales en el buffer (0–10)
33|  offlineCount: number;   // registros guardados offline pendientes de sync
34|  syncPending: () => Promise<{ processed: number; remaining: number; success: boolean }>;
35|  startTracking: () => void;
36|  stopTracking: () => void;
37|  isTracking: boolean;
38|}
39|
40|// ─── Helpers IndexedDB ────────────────────────────────────────────────────────
41|async function readCoordsByStatus(status: 'batch' | 'offline'): Promise<TelemetryCoord[]> {
42|  try {
43|    const db = await openDB();
44|    const tx = db.transaction('telemetry', 'readonly');
45|    const store = tx.objectStore('telemetry');
46|    return new Promise((resolve) => {
47|      const request = store.getAll();
48|      request.onsuccess = () => {
49|        const all = request.result || [];
50|        resolve(all.filter((x: any) => x.status === status));
51|      };
52|      request.onerror = () => resolve([]);
53|    });
54|  } catch (err) {
55|    console.error('IndexedDB read error:', err);
56|    return [];
57|  }
58|}
59|
60|async function writeBatchCoords(batch: TelemetryCoord[]): Promise<void> {
61|  try {
62|    const db = await openDB();
63|    const tx = db.transaction('telemetry', 'readwrite');
64|    const store = tx.objectStore('telemetry');
65|    
66|    return new Promise<void>((resolve) => {
67|      const allRequest = store.getAll();
68|      allRequest.onsuccess = () => {
69|        const all = allRequest.result || [];
70|        const batchKeys = all.filter((x: any) => x.status === 'batch').map((x: any) => x.ts);
71|        batchKeys.forEach((key: number) => store.delete(key));
72|        
73|        batch.forEach((coord) => {
74|          store.put({ ...coord, status: 'batch' });
75|        });
76|        resolve();
77|      };
78|      allRequest.onerror = () => resolve();
79|    });
80|  } catch (err) {
81|    console.error('IndexedDB writeBatch error:', err);
82|  }
83|}
84|
85|async function appendOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
86|  try {
87|    const db = await openDB();
88|    const tx = db.transaction('telemetry', 'readwrite');
89|    const store = tx.objectStore('telemetry');
90|    
91|    return new Promise<void>((resolve) => {
92|      const allRequest = store.getAll();
93|      allRequest.onsuccess = () => {
94|        const all = allRequest.result || [];
95|        const offlineRecords = all.filter((x: any) => x.status === 'offline');
96|        
97|        const merged = [...offlineRecords, ...coords];
98|        const toKeep = merged.slice(-MAX_OFFLINE_RECORDS);
99|        
100|        const toKeepKeys = new Set(toKeep.map((x) => x.ts));
101|        offlineRecords.forEach((x: any) => {
102|          if (!toKeepKeys.has(x.ts)) {
103|            store.delete(x.ts);
104|          }
105|        });
106|        
107|        toKeep.forEach((coord) => {
108|          store.put({ ...coord, status: 'offline' });
109|        });
110|        resolve();
111|      };
112|      allRequest.onerror = () => resolve();
113|    });
114|  } catch (err) {
115|    console.error('IndexedDB appendOffline error:', err);
116|  }
117|}
118|
119|async function clearOfflineCoords(): Promise<void> {
120|  try {
121|    const db = await openDB();
122|    const tx = db.transaction('telemetry', 'readwrite');
123|    const store = tx.objectStore('telemetry');
124|    return new Promise<void>((resolve) => {
125|      const allRequest = store.getAll();
126|      allRequest.onsuccess = () => {
127|        const all = allRequest.result || [];
128|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
129|        offlineKeys.forEach((key: number) => store.delete(key));
130|        resolve();
131|      };
132|      allRequest.onerror = () => resolve();
133|    });
134|  } catch (err) {
135|    console.error('IndexedDB clearOffline error:', err);
136|  }
137|}
138|
139|async function writeOfflineCoords(coords: TelemetryCoord[]): Promise<void> {
140|  try {
141|    const db = await openDB();
142|    const tx = db.transaction('telemetry', 'readwrite');
143|    const store = tx.objectStore('telemetry');
144|    return new Promise<void>((resolve) => {
145|      const allRequest = store.getAll();
146|      allRequest.onsuccess = () => {
147|        const all = allRequest.result || [];
148|        const offlineKeys = all.filter((x: any) => x.status === 'offline').map((x: any) => x.ts);
149|        offlineKeys.forEach((key: number) => store.delete(key));
150|
151|        coords.slice(-MAX_OFFLINE_RECORDS).forEach((coord) => {
152|          store.put({ ...coord, status: 'offline' });
153|        });
154|        resolve();
155|      };
156|      allRequest.onerror = () => resolve();
157|    });
158|  } catch (err) {
159|    console.error('IndexedDB writeOffline error:', err);
160|  }
161|}
162|
163|/**
164| * triggerKillSwitch — patrón centralizado de respuesta a 402.
165| *
166| * Antes había DOS copias casi idénticas de la limpieza de credenciales +
167| * lock en este hook (`flushBatch` y `syncOfflineQueue`), ambas
168| * llamadas `setLock(true, ...)` pero SÓLO UNA invalidaba el JWT en
169| * `localStorage`. Resultado: requests autenticadas zombie durante el
170| * grace period post-lock.
171| *
172| * Esta helper centraliza:
173| *   1. Detener tracking GPS (si se le pasa stopFn).
174| *   2. Limpiar claves de identidad (`tad_driver_user`, `TAD_DRIVER_JWT`).
175| *   3. Disparar `TAD_FORCE_LOGOUT` para suscriptores del evento.
176| *   4. Activar el PaymentLockOverlay vía `setLock(true)`.
177| *
178| * Vive como free function (no hook) porque la lógica no depende del
179| * estado del componente y se reutiliza desde dos `useCallback`.
180| */
181|function triggerKillSwitch(opts: {
182|  setLock: (locked: boolean, message?: string | null) => void;
183|  setConnectionStatus?: (s: 'online' | 'offline' | 'syncing') => void;
184|  stopTracking?: () => void;
185|}): void {
186|  const { setLock, setConnectionStatus, stopTracking } = opts;
187|  try {
188|    localStorage.removeItem('tad_driver_user');
189|    localStorage.removeItem('TAD_DRIVER_JWT');
190|    window.dispatchEvent(new CustomEvent('TAD_FORCE_LOGOUT', { detail: { reason: 'SUBSCRIPTION_UNPAID' } }));
191|  } catch {/* localStorage bloqueado no debe romper el flow */}
192|  if (stopTracking) stopTracking();
193|  if (setConnectionStatus) setConnectionStatus('offline');
194|  setLock(true, 'Suscripción vencida. Pago de RD$6,000 requerido.');
195|}
196|
197|// ─── Hook Principal ───────────────────────────────────────────────────────────
198|export function useTelemetry(): UseTelemetryReturn {
199|  const { setLock } = usePaymentStore();
200|
201|  const [connectionStatus, setConnectionStatus] = useState<ConnectionStatus>(
202|    typeof navigator !== 'undefined' && !navigator.onLine ? 'offline' : 'online'
203|  );
204|  const [batchCount, setBatchCount] = useState<number>(0);
205|  const [offlineCount, setOfflineCount] = useState<number>(0);
206|  const [isTracking, setIsTracking] = useState(false);
207|
208|  // Refs para evitar closures obsoletos
209|  const watchIdRef = useRef<number | null>(null);
210|  const flushTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
211|  const isOnlineRef = useRef(typeof navigator !== 'undefined' ? navigator.onLine : true);
212|  const wakeLockRef = useRef<any>(null); // Screen Wake Lock sentinel
213|
214|  // ─── Memoria persistente durante la sesión ─────────────────────────────
215|  const memoryBufferRef = useRef<TelemetryCoord[]>([]);
216|
217|  const resolveApiBase = useCallback(() => '/api/proxy', []);
218|
219|  // Hidratar contadores iniciales desde IndexedDB
220|  useEffect(() => {
221|    async function hydrate() {
222|      const batch = await readCoordsByStatus('batch');
223|      const offline = await readCoordsByStatus('offline');
224|      setBatchCount(batch.length);
225|      setOfflineCount(offline.length);
226|    }
227|    hydrate();
228|  }, []);
229|
230|  const buildTelemetryPayload = useCallback((driverId: string, deviceId: string, points: TelemetryCoord[]) => {
231|    return {
232|      driverId,
233|      deviceId,
234|      points: points.map((coord) => ({
235|        lat: coord.lat,
236|        lng: coord.lng,
237|        speed: 0,
238|        timestamp: coord.ts,
239|      })),
240|    };
241|  }, []);
242|
243|  const postTrackBatch = useCallback(async (
244|    apiBase: string,
245|    driverId: string,
246|    deviceId: string,
247|    points: TelemetryCoord[]
248|  ) => {
249|    return fetch(`${apiBase}/fleet/track-batch`, {
250|      method: 'POST',
251|      headers: { 'Content-Type': 'application/json' },
252|      credentials: 'include',
253|      body: JSON.stringify(buildTelemetryPayload(driverId, deviceId, points)),
254|      signal: AbortSignal.timeout(15_000),
255|    });
256|  }, [buildTelemetryPayload]);
257|
258|  const syncOfflineQueue = useCallback(async (
259|    apiBase: string,
260|    driverId: string,
261|    deviceId: string
262|  ) => {
263|    const DRIP_CHUNK_SIZE = 50;
264|    let processed = 0;
265|    let remainingQueue = await readCoordsByStatus('offline');
266|
267|    while (remainingQueue.length > 0) {
268|      const chunk = remainingQueue.slice(0, DRIP_CHUNK_SIZE);
269|
270|      try {
271|        const retryRes = await postTrackBatch(apiBase, driverId, deviceId, chunk);
272|        if (retryRes.status === 402) {
273|          triggerKillSwitch({ setLock });
274|          break;
275|        }
