2| * TAD DOOH - Next.js API Proxy
3| *
4| * Este proxy elimina el 100% de los errores CORS y 502 por URL vacía.
5| * Las variables de entorno en este archivo se leen en RUNTIME (no build-time),
6| * por lo que funcionan correctamente en EasyPanel Free Tier.
7| *
8| * Flujo: Browser → /api/proxy/* → NestJS backend (server-to-server)
9| */
10|
11|import type { NextApiRequest, NextApiResponse } from 'next';
12|
13|// BACKEND_INTERNAL_URL = variable de entorno del servidor (runtime, no build-time)
14|// En EasyPanel: configurar como Environment Variable normal (NO Build Arg)
15|// Opciones en orden de prioridad:
16|//   1. BACKEND_INTERNAL_URL=http://api:3000  (red interna Docker de EasyPanel - más rápido)
17|//   2. NEXT_PUBLIC_API_URL=https://...easypanel.host/api  (URL pública - fallback)
18|//   3. URL hardcodeada - último recurso
19|// Normalizar la URL base del backend:
20|// - BACKEND_INTERNAL_URL = http://api:3000  (red interna EasyPanel - PRIORIDAD)
21|// - NEXT_PUBLIC_API_URL puede ser https://host/api o https://host/api/v1 → extraemos solo el host
22|// - Fallback hardcodeado como última instancia
23|const rawBackendUrl = (
24|  process.env.INTERNAL_BACKEND_URL
25|  || process.env.BACKEND_INTERNAL_URL
26|  || process.env.BACKEND_URL
27|  || process.env.NEXT_PUBLIC_API_URL
28|  || 'https://proyecto-ia-tad-api.rewvid.easypanel.host'
29|);
30|
31|// Strip any trailing /api, /api/v1, or / to get a clean base
32|const BACKEND_BASE = rawBackendUrl
33|  .replace(/\/api\/v1\/?$/, '')
34|  .replace(/\/api\/?$/, '')
35|  .replace(/\/$/, '');
36|
37|// Diagnostic removed for Zero-Waste audit.
38|
39|export const config = {
40|  api: {
41|    bodyParser: false,
42|    externalResolver: true,
43|    responseLimit: false,
44|  },
45|};
46|
47|export default async function handler(req: NextApiRequest, res: NextApiResponse) {
48|  const { path } = req.query;
49|  const requestOrigin = typeof req.headers.origin === 'string' ? req.headers.origin : '';
50|
51|  // Health check especial para diagnóstico de red
52|  if (req.method === 'GET' && Array.isArray(path) && path[0] === '_proxy_health') {
53|    return res.status(200).json({
54|      proxy: 'OK',
55|      backendTarget: `${BACKEND_BASE}/api/v1/`,
56|      envSource: process.env.INTERNAL_BACKEND_URL ? 'INTERNAL_BACKEND_URL' :
57|                 process.env.BACKEND_INTERNAL_URL ? 'BACKEND_INTERNAL_URL' : 
58|                 process.env.BACKEND_URL ? 'BACKEND_URL' :
59|                 process.env.NEXT_PUBLIC_API_URL ? 'NEXT_PUBLIC_API_URL' : 'HARDCODED',
60|      timestamp: new Date().toISOString(),
61|    });
62|  }
63|
64|  // Construir ruta del backend
65|  const pathStr = Array.isArray(path) ? path.join('/') : (path || '');
66|
67|  // Construir query string (excluyendo el parámetro 'path' de la ruta dinámica)
68|  const queryParams = Object.entries(req.query)
69|    .filter(([key]) => key !== 'path')
70|    .map(([k, v]) => [k, Array.isArray(v) ? v[0] : (v || '')] as [string, string]);
71|  const queryString = queryParams.length > 0
72|    ? '?' + new URLSearchParams(queryParams).toString()
