88|
89|  try {
90|    const getForwardHeaders = (target: string) => {
91|      const headers = { ...req.headers } as Record<string, string>;
92|      
93|      // 🔑 Reenviar el token al backend
94|      let authHeader = req.headers.authorization || req.headers.Authorization;
95|      
96|      if (!authHeader) {
97|        const cookieToken = req.cookies['sb-access-token'];
98|        if (cookieToken) {
99|          authHeader = `Bearer ${cookieToken}`;
