122|
123|      const rawCookie = req.headers.cookie;
124|      if (rawCookie) {
125|        headers['cookie'] = Array.isArray(rawCookie) ? rawCookie.join('; ') : rawCookie;
126|      }
127|
128|      return headers;
129|    };
130|
131|    const fetchOptions: RequestInit = {
