142|    // --- REGLA DE RESILIENCIA TAD ---
143|    let backendResponse: Response | undefined;
144|    try {
145|      backendResponse = await fetch(targetUrl, fetchOptions);
146|    } catch (fetchError: unknown) {
147|      const errorMessage = fetchError instanceof Error ? fetchError.message : String(fetchError);
