149|      const isNetworkError = errorMessage.includes('fetch failed') || 
150|                            errorMessage.includes('ENOTFOUND') || 
151|                            errorMessage.includes('ECONNREFUSED') ||
152|                            errorMessage.includes('ETIMEDOUT') ||
153|                            errorMessage.includes('EAI_AGAIN');
154|      
155|      if (isNetworkError && (BACKEND_BASE.includes('api:3000') || BACKEND_BASE.includes('localhost'))) {
156|        const publicFallback = 'https://proyecto-ia-tad-api.rewvid.easypanel.host/api/v1';
157|        const fallbackUrl = `${publicFallback}/${pathStr}${queryString}`;
158|        console.warn(`[PROXY] 🔄 Reintentando vía pública por error de red: ${errorMessage} -> ${fallbackUrl}`);
159|        
160|        // REGENAR HEADERS: El host cambió a la URL pública
161|        fetchOptions.headers = getForwardHeaders(fallbackUrl);
162|        
163|        try {
164|          backendResponse = await fetch(fallbackUrl, fetchOptions);
165|        } catch (fallbackError: unknown) {
166|          console.error(`[PROXY] ❌ Fallback también falló: ${fallbackError instanceof Error ? fallbackError.message : String(fallbackError)}`);
167|          throw fallbackError;
168|        }
169|      } else {
170|        throw fetchError; 
171|      }
172|    }
173|
174|    // Verificación de seguridad para evitar "Cannot read properties of undefined (reading 'headers')"
175|    if (!backendResponse) {
176|      throw new Error('Backend response is undefined after all attempts');
177|    }
178|
179|    if (backendResponse.status === 401) {
180|      const hasOriginalHeader = !!(req.headers.authorization || req.headers.Authorization);
181|      const hasCookieToken = !!req.cookies['sb-access-token'];
182|      const authStatus = hasOriginalHeader ? 'PRESENTE' : (hasCookieToken ? 'FALLBACK_COOKIE' : 'AUSENTE');
183|      
184|      console.error(`[PROXY 401] Backend rechazó credenciales: ${pathStr} | Auth: ${authStatus}`);
185|    }
186|
187|    // Headers CORS de respuesta
188|    if (requestOrigin) {
189|      res.setHeader('Access-Control-Allow-Origin', requestOrigin);
190|      res.setHeader('Vary', 'Origin');
191|    }
192|    res.setHeader('Access-Control-Allow-Methods', 'GET,POST,PUT,DELETE,PATCH,OPTIONS');
193|    res.setHeader('Access-Control-Allow-Credentials', 'true');
194|
195|    const contentType = backendResponse.headers.get('content-type');
196|    if (contentType) res.setHeader('Content-Type', contentType);
197|    const contentDisp = backendResponse.headers.get('content-disposition');
198|    if (contentDisp) res.setHeader('Content-Disposition', contentDisp);
199|    const contentLength = backendResponse.headers.get('content-length');
200|    if (contentLength) res.setHeader('Content-Length', contentLength);
201|
202|    const buffer = Buffer.from(await backendResponse.arrayBuffer());
203|
204|    if (!backendResponse.ok) {
205|      const rawBody = buffer.toString('utf-8');
206|      console.error(`[PROXY BACKEND ERROR] ${req.method} ${targetUrl} -> ${backendResponse.status} ${backendResponse.statusText} | body: ${rawBody.slice(0, 500)}`);
207|
208|      if (contentType?.includes('application/json')) {
209|        try {
